/**
 * Experimental P&ID studio panel.
 * Renders sheets generated by the IPC engine (window.omniEngAPI.generatePID).
 * All DOM construction uses createElement/appendChild/textContent; the engine
 * SVG string is parsed with DOMParser and never assigned via innerHTML.
 */

class PIDStudioUI {
  constructor(containerId) {
    this.container = document.getElementById(containerId);
    this.sheets = [];
    this.schedule = null;
    this.validation = null;
    this.note = '';
    this.activeSheetIndex = 0;
    this.activeCategory = 'equipment';
    this.zoom = 1;
    this.generating = false;
    this.scheduleFilter = '';
    this._lastElapsedMs = null;
    this.svgNode = null;
    this.elements = null;
  }

  render() {
    if (!this.container) return;

    const panel = document.createElement('div');
    panel.id = 'pid-studio-panel';

    const header = document.createElement('div');
    header.className = 'pid-header';
    header.style.cssText = 'display:flex; align-items:center; gap:8px; flex-wrap:wrap;';

    const title = document.createElement('span');
    title.textContent = 'P&ID Studio (experimental)';
    title.style.cssText = 'font-weight:600; font-size:13px;';

    const templateSelect = document.createElement('select');
    templateSelect.id = 'pid-template-select';
    templateSelect.className = 'ribbon-select';
    templateSelect.style.cssText = 'padding:4px 8px; font-size:11px;';
    const templateOption = document.createElement('option');
    templateOption.value = 'oilgas';
    templateOption.textContent = 'oilgas — Oil & Gas Production Facility';
    templateSelect.append(templateOption);

    const lngOption = document.createElement('option');
    lngOption.value = 'lng';
    lngOption.textContent = 'lng — LNG Receiving & Liquefaction Facility';
    templateSelect.append(lngOption);

    const btnGenerate = document.createElement('button');
    btnGenerate.type = 'button';
    btnGenerate.className = 'btn btn-primary';
    btnGenerate.textContent = 'Generate P&ID';

    header.append(title, templateSelect, btnGenerate);

    const exportRow = document.createElement('div');
    exportRow.className = 'pid-export-row';

    const btnDownloadSvg = document.createElement('button');
    btnDownloadSvg.type = 'button';
    btnDownloadSvg.className = 'btn';
    btnDownloadSvg.textContent = 'Download SVG';
    btnDownloadSvg.disabled = true;

    const btnDownloadCsv = document.createElement('button');
    btnDownloadCsv.type = 'button';
    btnDownloadCsv.className = 'btn';
    btnDownloadCsv.textContent = 'Download Schedule CSV';
    btnDownloadCsv.disabled = true;

    const btnDownloadTxt = document.createElement('button');
    btnDownloadTxt.type = 'button';
    btnDownloadTxt.className = 'btn';
    btnDownloadTxt.textContent = 'Download Validation TXT';
    btnDownloadTxt.disabled = true;

    const btnPrint = document.createElement('button');
    btnPrint.type = 'button';
    btnPrint.className = 'btn';
    btnPrint.textContent = 'Print';

    exportRow.append(btnDownloadSvg, btnDownloadCsv, btnDownloadTxt, btnPrint);

    const preview = document.createElement('div');
    preview.id = 'pid-preview';
    preview.className = 'pid-preview';

    const zoomBar = document.createElement('div');
    zoomBar.className = 'pid-zoom-bar';
    const btnZoomOut = this._makeZoomButton('−', () => this._zoomBy(1 / 1.25));
    const btnZoomIn = this._makeZoomButton('+', () => this._zoomBy(1.25));
    const btnZoomReset = this._makeZoomButton('100%', () => this._setZoom(1));
    const btnZoomFit = this._makeZoomButton('Fit', () => this._fitZoom());
    const zoomLabel = document.createElement('span');
    zoomLabel.className = 'pid-zoom-label';
    zoomLabel.textContent = '100%';
    zoomBar.append(btnZoomOut, btnZoomReset, btnZoomIn, btnZoomFit, zoomLabel);

    const tabStrip = document.createElement('div');
    tabStrip.className = 'pid-sheet-tabs';
    const previewHost = document.createElement('div');
    previewHost.className = 'pid-preview-host';
    preview.append(zoomBar, tabStrip, previewHost);

    const validationPane = document.createElement('div');
    validationPane.className = 'pid-validation';

    const schedulePane = document.createElement('div');
    schedulePane.className = 'pid-schedule';
    const scheduleFilterRow = document.createElement('div');
    scheduleFilterRow.className = 'pid-schedule-filter-row';
    const filterInput = document.createElement('input');
    filterInput.type = 'text';
    filterInput.className = 'pid-filter-input';
    filterInput.placeholder = 'Filter…';
    scheduleFilterRow.append(filterInput);
    const scheduleTabs = document.createElement('div');
    scheduleTabs.className = 'pid-schedule-tabs';
    const scheduleBody = document.createElement('div');
    scheduleBody.className = 'pid-schedule-body';
    schedulePane.append(scheduleFilterRow, scheduleTabs, scheduleBody);

    const status = document.createElement('div');
    status.className = 'pid-statusline';
    status.textContent = 'No sheet generated yet.';

    panel.append(header, exportRow, preview, validationPane, schedulePane, status);
    this.container.replaceChildren(panel);

    this.elements = {
      btnGenerate,
      btnDownloadSvg,
      btnDownloadCsv,
      btnDownloadTxt,
      btnPrint,
      templateSelect,
      tabStrip,
      previewHost,
      zoomLabel,
      filterInput,
      scheduleFilterRow,
      validationPane,
      scheduleTabs,
      scheduleBody,
      status
    };

    btnGenerate.addEventListener('click', async () => {
      const value = templateSelect.value || 'oilgas';
      await this.generate(value);
    });
    btnDownloadSvg.addEventListener('click', () => this.downloadSvg());
    btnDownloadCsv.addEventListener('click', () => this.downloadCsv());
    btnDownloadTxt.addEventListener('click', () => this.downloadValidationTxt());
    btnPrint.addEventListener('click', () => this.printSheet());

    previewHost.addEventListener(
      'wheel',
      (e) => {
        e.preventDefault();
        this._zoomBy(Math.exp(-e.deltaY * 0.0012));
      },
      { passive: false }
    );

    filterInput.addEventListener('input', () => {
      this.scheduleFilter = filterInput.value;
      this._renderScheduleTable(scheduleBody, this.activeCategory, this.schedule || {});
    });

    window.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const modal = document.getElementById('modal-pid-studio');
      if (!modal || !modal.classList || !modal.classList.contains('active')) return;
      modal.classList.remove('active');
      const ribbonBtn = document.getElementById('ribbon-btn-pid');
      if (ribbonBtn && ribbonBtn.classList) {
        ribbonBtn.classList.remove('active');
        ribbonBtn.classList.remove('pressed');
      }
    });
  }

  _makeZoomButton(label, handler) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn pid-zoom-btn';
    btn.textContent = label;
    btn.addEventListener('click', handler);
    return btn;
  }

  _now() {
    return typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
  }

  async generate(template) {
    if (!this.elements) return;
    if (!window.omniEngAPI || typeof window.omniEngAPI.generatePID !== 'function') {
      this._showStatusError('Generation service unavailable: window.omniEngAPI.generatePID was not found.');
      return;
    }
    const start = this._now();
    this._setGenerating(true);
    try {
      const result = await window.omniEngAPI.generatePID({ template });
      this._lastElapsedMs = this._now() - start;
      this._applyResult(result);
    } catch (err) {
      this._lastElapsedMs = this._now() - start;
      this._showStatusError(err && err.message ? err.message : String(err));
    } finally {
      this._setGenerating(false);
    }
  }

  _setGenerating(busy) {
    this.generating = busy;
    if (this.elements.btnGenerate) {
      this.elements.btnGenerate.disabled = busy;
      this.elements.btnGenerate.textContent = busy ? 'Generating…' : 'Generate P&ID';
    }
    const modal = document.getElementById('modal-pid-studio');
    if (modal) {
      if (busy) modal.setAttribute('aria-busy', 'true');
      else modal.removeAttribute('aria-busy');
    }
  }

  _showStatusError(message) {
    const status = this.elements.status;
    status.setAttribute('role', 'alert');
    status.classList.add('pid-error-alert');
    status.textContent = 'Generation failed: ' + message;
  }

  downloadSvg() {
    if (this.sheets.length === 0) return;
    const index = Math.min(this.activeSheetIndex, this.sheets.length - 1);
    const sheet = this.sheets[index];
    if (!sheet || typeof sheet.svg !== 'string') return;
    const blob = new Blob([sheet.svg], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    const sheetNumber = sheet.sheetNumber != null ? sheet.sheetNumber : index + 1;
    anchor.download = 'omnieng_pid_sheet_' + sheetNumber + '.svg';
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  downloadCsv() {
    if (!this.schedule) return;
    const categories = ['equipment', 'lines', 'instruments', 'valves', 'controlLoops'];
    const sections = [];
    for (const category of categories) {
      const rows = Array.isArray(this.schedule[category]) ? this.schedule[category] : [];
      sections.push('# ' + category + '\n' + this.scheduleToCsv(category, rows));
    }
    const csv = sections.join('\n\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = 'omnieng_pid_schedule.csv';
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  downloadValidationTxt() {
    const errors = Array.isArray(this.validation && this.validation.errors) ? this.validation.errors : [];
    const warnings = Array.isArray(this.validation && this.validation.warnings) ? this.validation.warnings : [];
    const lines = [];
    lines.push('OmniEng P&ID Validation Report');
    lines.push('=================================');
    lines.push('');
    lines.push('Errors: ' + errors.length);
    for (const error of errors) lines.push('- ' + this._messageText(error));
    lines.push('');
    lines.push('Warnings: ' + warnings.length);
    for (const warning of warnings) lines.push('- ' + this._messageText(warning));
    if (this.note) {
      lines.push('');
      lines.push('Note: ' + this.note);
    }
    const blob = new Blob([lines.join('\n')], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = 'omnieng_pid_validation.txt';
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  printSheet() {
    if (typeof window !== 'undefined' && typeof window.print === 'function') window.print();
  }

  _zoomBy(factor) {
    const next = Math.max(0.1, Math.min(8, this.zoom * factor));
    this._setZoom(next);
  }

  _setZoom(zoom) {
    this.zoom = zoom;
    this._applyZoomToSvg();
    if (this.elements && this.elements.zoomLabel) {
      this.elements.zoomLabel.textContent = Math.round(zoom * 100) + '%';
    }
  }

  _applyZoomToSvg() {
    const svg = this.svgNode;
    if (!svg) return;
    svg.style.transformOrigin = 'center';
    svg.style.transform = 'scale(' + this.zoom + ')';
  }

  _fitZoom() {
    const host = this.elements.previewHost;
    const svg = this.svgNode;
    if (!host || !svg) return;
    const hostWidth = host.clientWidth || host.getBoundingClientRect().width || 800;
    let baseWidth = 1189;
    if (svg.viewBox && svg.viewBox.baseVal && typeof svg.viewBox.baseVal.width === 'number' && svg.viewBox.baseVal.width > 0) {
      baseWidth = svg.viewBox.baseVal.width;
    } else {
      const vb = svg.getAttribute ? svg.getAttribute('viewBox') : null;
      if (vb) {
        const parts = String(vb).split(/[\s,]+/).map(Number);
        if (parts.length === 4 && parts[2] > 0) baseWidth = parts[2];
      }
    }
    const scale = Math.max(0.1, Math.min(3, (hostWidth - 32) / baseWidth));
    this._setZoom(scale);
  }

  scheduleToCsv(category, rows) {
    const itemRows = Array.isArray(rows)
      ? rows.filter((row) => row && typeof row === 'object' && !Array.isArray(row))
      : [];
    const specs = this._columnSpecsFor(category, itemRows);
    const lines = [specs.map((spec) => this._csvEscape(spec.label)).join(',')];
    for (const row of itemRows) {
      lines.push(specs.map((spec) => this._csvEscape(this._cellText(row, spec.keys))).join(','));
    }
    return lines.join('\n');
  }

  _applyResult(result) {
    if (!this.elements) return;
    const sheets = Array.isArray(result && result.sheets) ? result.sheets : [];
    const schedule = result && result.schedule && typeof result.schedule === 'object' ? result.schedule : {};
    const validation = result && result.validation && typeof result.validation === 'object' ? result.validation : {};
    const note = typeof (result && result.note) === 'string' ? result.note : '';
    this.sheets = sheets;
    this.schedule = schedule;
    this.validation = validation;
    this.note = note;
    this.activeSheetIndex = 0;
    this.elements.btnDownloadSvg.disabled = sheets.length === 0;
    this.elements.btnDownloadCsv.disabled = Object.keys(schedule).length === 0;
    this.elements.btnDownloadTxt.disabled = Object.keys(validation).length === 0;
    if (this.elements.scheduleFilterRow) {
      this.elements.scheduleFilterRow.style.display = Object.keys(schedule).length === 0 ? 'none' : '';
    }
    this._renderSheetTabs();
    if (sheets.length > 0) {
      this._showSheet(0);
    } else {
      this.elements.previewHost.replaceChildren();
      this.svgNode = null;
    }
    this._renderValidation(validation, note);
    this._renderSchedule(schedule);
    this._renderStatus(sheets);
  }

  _renderSheetTabs() {
    const tabStrip = this.elements.tabStrip;
    tabStrip.replaceChildren();
    this.sheets.forEach((sheet, index) => {
      const tab = document.createElement('button');
      tab.type = 'button';
      tab.className = 'pid-sheet-tab';
      tab.textContent = 'Sheet ' + (sheet.sheetNumber != null ? sheet.sheetNumber : index + 1);
      if (index === this.activeSheetIndex) tab.classList.add('active');
      tab.addEventListener('click', () => this._showSheet(index));
      tabStrip.append(tab);
    });
  }

  _showSheet(index) {
    this.activeSheetIndex = index;
    const tabStrip = this.elements.tabStrip;
    Array.from(tabStrip.children).forEach((child, childIndex) => {
      child.classList.toggle('active', childIndex === index);
    });
    const host = this.elements.previewHost;
    host.replaceChildren();
    const sheet = this.sheets[index];
    if (!sheet || typeof sheet.svg !== 'string') {
      const empty = document.createElement('div');
      empty.className = 'pid-empty-state';
      empty.textContent = 'No SVG content available for this sheet.';
      host.append(empty);
      this.svgNode = null;
      return;
    }
    let node = null;
    let parseError = null;
    try {
      const doc = new DOMParser().parseFromString(sheet.svg, 'image/svg+xml');
      node = doc.documentElement;
      if (!node || node.nodeName.toLowerCase() !== 'svg') {
        const errorNode = doc.querySelector('parsererror');
        parseError = errorNode ? errorNode.textContent.trim() : 'SVG parse failed';
        node = null;
      }
    } catch (err) {
      parseError = err.message || String(err);
    }
    if (!node) {
      const empty = document.createElement('div');
      empty.className = 'pid-empty-state';
      empty.textContent = 'Could not parse engine SVG: ' + (parseError || 'unknown error');
      host.append(empty);
      this.svgNode = null;
      return;
    }
    host.appendChild(node);
    this.svgNode = node;
    this._applyZoomToSvg();
  }

  _renderValidation(validation, note) {
    const pane = this.elements.validationPane;
    pane.replaceChildren();
    const heading = document.createElement('div');
    heading.className = 'pid-pane-title';
    heading.textContent = 'Validation';
    pane.append(heading);
    const errors = Array.isArray(validation.errors) ? validation.errors : [];
    const warnings = Array.isArray(validation.warnings) ? validation.warnings : [];
    for (const error of errors) {
      const item = document.createElement('div');
      item.className = 'pid-validation-error';
      item.textContent = this._messageText(error);
      pane.append(item);
    }
    for (const warning of warnings) {
      const item = document.createElement('div');
      item.className = 'pid-validation-warning';
      item.textContent = this._messageText(warning);
      pane.append(item);
    }
    if (note) {
      const item = document.createElement('div');
      item.className = 'pid-note';
      item.textContent = note;
      pane.append(item);
    }
    if (errors.length === 0 && warnings.length === 0 && !note) {
      const empty = document.createElement('div');
      empty.className = 'pid-empty-state';
      empty.textContent = 'No issues reported.';
      pane.append(empty);
    }
  }

  _renderSchedule(schedule) {
    const top = this.elements.scheduleTabs;
    const body = this.elements.scheduleBody;
    const filterInput = this.elements.filterInput;
    top.replaceChildren();
    const categories = [
      ['equipment', 'Equipment'],
      ['lines', 'Lines'],
      ['instruments', 'Instruments'],
      ['valves', 'Valves'],
      ['controlLoops', 'Control Loops']
    ];
    for (const [key, label] of categories) {
      const tab = document.createElement('button');
      tab.type = 'button';
      tab.className = 'pid-schedule-tab';
      tab.textContent = label;
      if (key === this.activeCategory) tab.classList.add('active');
      tab.addEventListener('click', () => {
        this.activeCategory = key;
        top.querySelectorAll('.pid-schedule-tab').forEach((t) => {
          t.classList.toggle('active', t === tab);
        });
        if (filterInput) filterInput.placeholder = 'Filter ' + label.toLowerCase() + '…';
        this._renderScheduleTable(body, key, schedule);
      });
      top.append(tab);
    }
    if (filterInput) {
      const currentLabel = categories.find(([key]) => key === this.activeCategory);
      filterInput.placeholder = 'Filter ' + (currentLabel ? currentLabel[1].toLowerCase() : 'entries') + '…';
    }
    this._renderScheduleTable(body, this.activeCategory, schedule);
  }

  _renderScheduleTable(body, category, schedule) {
    body.replaceChildren();
    const rows = Array.isArray(schedule && schedule[category]) ? schedule[category] : [];
    const specs = this._columnSpecsFor(category, rows);
    const query = (this.scheduleFilter || '').trim().toLowerCase();
    let visibleRows = rows;
    if (query) {
      visibleRows = rows.filter((row) =>
        specs.some((spec) => this._cellText(row, spec.keys).toLowerCase().includes(query))
      );
    }
    if (specs.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'pid-empty-state';
      empty.textContent = 'No entries available for this category.';
      body.append(empty);
      return;
    }
    const table = document.createElement('table');
    table.className = 'pid-schedule-table';
    const thead = document.createElement('thead');
    const headRow = document.createElement('tr');
    for (const spec of specs) {
      const th = document.createElement('th');
      th.textContent = spec.label;
      headRow.append(th);
    }
    thead.append(headRow);
    const tbody = document.createElement('tbody');
    if (rows.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = specs.length;
      td.textContent = 'No entries.';
      tr.append(td);
      tbody.append(tr);
    } else if (visibleRows.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = specs.length;
      td.textContent = 'No entries match your filter.';
      tr.append(td);
      tbody.append(tr);
    } else {
      for (const row of visibleRows) {
        const tr = document.createElement('tr');
        for (const spec of specs) {
          const td = document.createElement('td');
          td.textContent = this._cellText(row, spec.keys);
          tr.append(td);
        }
        tbody.append(tr);
      }
    }
    table.append(thead, tbody);
    body.append(table);
  }

  _renderStatus(sheets) {
    const status = this.elements.status;
    status.removeAttribute('role');
    status.classList.remove('pid-error-alert');
    if (sheets.length === 0) {
      status.textContent = 'No sheet generated yet.';
      return;
    }
    const sheet = sheets[0];
    const format = typeof sheet.format === 'string' && sheet.format !== '' ? sheet.format : 'A0';
    const widthMm = Number.isFinite(sheet.widthMm) ? sheet.widthMm : 1189;
    const heightMm = Number.isFinite(sheet.heightMm) ? sheet.heightMm : 841;
    const scale = this._formatScale(sheet.scale);
    let text =
      'Generated sheet 1/' +
      sheets.length +
      ' (' +
      format +
      ', ' +
      widthMm +
      '×' +
      heightMm +
      ' mm, scale ' +
      scale +
      ')';
    if (this._lastElapsedMs != null) {
      text += ' in ' + (this._lastElapsedMs / 1000).toFixed(2) + ' s';
    }
    status.textContent = text;
  }

  _formatScale(scale) {
    if (scale === undefined || scale === null || scale === '') return '1:50';
    if (typeof scale === 'number') return '1:' + scale;
    const s = String(scale).trim();
    if (/^\d+$/.test(s)) return '1:' + s;
    return s;
  }

  _messageText(value) {
    if (value === undefined || value === null) return '';
    if (typeof value === 'string') return value;
    if (typeof value.message === 'string') return value.message;
    return String(value);
  }

  _categoryColumnSpecs() {
    return {
      equipment: [
        { label: 'Tag', keys: ['tag', 'id'] },
        { label: 'Type', keys: ['type'] },
        { label: 'Description', keys: ['description', 'desc', 'name'] },
        { label: 'Size', keys: ['size', 'dimension'] },
        { label: 'Nozzles', keys: ['nozzles'] }
      ],
      lines: [
        { label: 'Line Number', keys: ['lineNumber', 'number', 'tag'] },
        { label: 'From', keys: ['from'] },
        { label: 'To', keys: ['to'] },
        { label: 'Service', keys: ['service', 'description', 'desc'] },
        { label: 'Diameter', keys: ['diameter', 'diameterIn'] },
        { label: 'Specification', keys: ['spec', 'specification', 'pipingClass'] }
      ],
      instruments: [
        { label: 'Tag', keys: ['tag', 'id'] },
        { label: 'Type', keys: ['type'] },
        { label: 'Function', keys: ['function', 'description', 'desc'] },
        { label: 'Connected To', keys: ['connectedTo'] },
        { label: 'Location', keys: ['location', 'area'] }
      ],
      valves: [
        { label: 'Tag', keys: ['tag', 'id'] },
        { label: 'Type', keys: ['type'] },
        { label: 'Size', keys: ['size', 'diameter'] },
        { label: 'Actuator', keys: ['actuator', 'operator'] },
        { label: 'Set Pressure (barg)', keys: ['setPressureBarg', 'setPressure'] }
      ],
      controlLoops: [
        { label: 'Loop Tag', keys: ['tag', 'id', 'loopId'] },
        { label: 'Name', keys: ['name', 'description', 'desc'] },
        { label: 'Sensor', keys: ['sensor'] },
        { label: 'Controller', keys: ['controller'] },
        { label: 'Final Element', keys: ['finalElement'] }
      ]
    };
  }

  _columnSpecsFor(category, rows) {
    const specMap = this._categoryColumnSpecs();
    const specs = (specMap[category] || []).map((spec) => ({ label: spec.label, keys: spec.keys.slice() }));
    const usedKeys = new Set();
    for (const spec of specs) {
      for (const key of spec.keys) usedKeys.add(key);
    }
    const seen = new Set();
    for (const row of rows) {
      for (const key of Object.keys(row)) {
        if (usedKeys.has(key) || seen.has(key)) continue;
        seen.add(key);
        specs.push({ label: this._prettifyKey(key), keys: [key] });
      }
    }
    return specs;
  }

  _prettifyKey(key) {
    const words = String(key)
      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .split(/[\s_]+/);
    return words
      .filter((word) => word.length > 0)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  _cellText(row, keys) {
    for (const key of keys) {
      const value = row[key];
      if (value === undefined || value === null) continue;
      const text = this._scalarText(value);
      if (text !== '') return text;
    }
    return '';
  }

  _scalarText(value) {
    if (typeof value === 'string') return value.trim();
    if (typeof value === 'number' || typeof value === 'boolean') return String(value);
    if (Array.isArray(value)) {
      return value
        .map((item) => this._scalarText(item))
        .filter((text) => text !== '')
        .join('; ');
    }
    if (value && typeof value === 'object') {
      const picked =
        value.tag ?? value.id ?? value.name ?? value.label ?? value.loopId ?? value.lineNumber ?? value.number;
      if (picked !== undefined && picked !== null) return String(picked);
      return '';
    }
    return '';
  }

  _csvEscape(value) {
    const text = String(value === undefined || value === null ? '' : value);
    if (/[",\r\n]/.test(text)) {
      return '"' + text.replace(/"/g, '""') + '"';
    }
    return text;
  }
}

if (typeof window !== 'undefined') {
  window.PIDStudioUI = PIDStudioUI;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { PIDStudioUI };
}
